void adjust_bpf_jumps_offsets(struct bpf_prog *prog, int pos, int delta) {
    int i;
    struct bpf_insn *insn;

    for (i = 0; i < prog->len; i++) {
        insn = &prog->insnsi[i];
        if ((insn->code & BPF_CLASS_MASK) != BPF_JMP)
            continue;

        if ((insn->jt || insn->jf) && /* Skip call or exit */
            (insn->code != BPF_JMP_A) && /* Skip special case of JMP A (return) */
            (i >= pos)) {
            insn->off -= delta;
        }
    }
}

void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta) {
    for (int i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &prog->insnsi[i];
        if ((insn->code & BPF_CLASS_MASK) != BPF_JMP)
            continue;
        if (insn->off == 0 || insn->off == BPF_EXIT)
            continue;
        if (i < pos && i + insn->off >= pos)
            insn->off += delta;
        else if (i >= pos && i + insn->off < pos)
            insn->off -= delta;
    }
}

void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta)
{
    int i;
    struct bpf_insn *insn;

    for (i = 0; i < prog->len; i++) {
        insn = &prog->insnsi[i];

        /* Check if the instruction is a jump (JMP) and not a call or exit */
        if ((insn->code & 0xf0) != 0x60)
            continue;

        if (insn->code == (BPF_JMP | BPF_JA))
            continue; /* Skip unconditional jump (exit) */
        if (insn->code == (BPF_JMP | BPF_CALL))
            continue; /* Skip function call */

        /* Adjust the offset if the instruction is beyond the specified position */
        if (i >= pos)
            insn->off += delta;
    }
}

void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta)
{
    int i;
    struct bpf_insn *insns = prog->insnsi;

    for (i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &insns[i];

        /* Only adjust jump instructions that are not calls or exits */
        if ((insn->code & BPF_CLASS_MASK) != BPF_JMP)
            continue;
        if (insn->code == (BPF_JMP | BPF_CALL) || insn->code == (BPF_JMP | BPF_EXIT))
            continue;

        /* Adjust the offset if it is relative to the specified position */
        if (i >= pos)
            insn->off -= delta;
    }
}

void adjust_bpf_jump_offsets(struct bpf_prog *prog, int pos, int delta) {
    for (int i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &prog->insnsi[i];
        if ((BPF_CLASS(insn->code) == BPF_JMP) && 
            (BPF_OP(insn->code) != BPF_CALL) && 
            (BPF_OP(insn->code) != BPF_EXIT)) {
            if (insn->off >= pos) {
                insn->off += delta;
            }
        }
    }
}
